// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

// https://iquilezles.org/articles/warp/

// background
let theShader, t;

// foreground
let squares = [];
let margin = 1, N = 12, u;
let col;

let randInt = (a, b) => (floor(random(a, b))); 

function preload() {
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(500, 500, WEBGL);
	pixelDensity(4);
  noStroke();
  ortho();
  u = width/N;
  col = random(["#abcd5e", "#62b6de", "#f589a3", "#ef562f", "#fc8405", "#f9d531"]);
  createComposition();
	t = random(10000);
}

function draw() {
  background("#fffbe6");
  translate(-width/2, -height/2);

  theShader.setUniform("u_resolution", [width / 1, height / 1]);
	theShader.setUniform("u_time", t);

  let col1 = color("#fffbe6");
  let r1 = red(col1)/255;
  let g1 = green(col1)/255;
  let b1 = blue(col1)/255;
  let col2 = color(5);
  let r2 = red(col2)/255;
  let g2 = green(col2)/255;
  let b2 = blue(col2)/255;
  shadedSquare(margin*u, margin*u, width-2*margin*u, r1, g1, b1, r2, g2, b2);

	randomSeed(0);
  for (let squ of squares) {
    var col1 = "#fffbe6";
    var r1 = red(col1)/255;
    var g1 = green(col1)/255;
    var b1 = blue(col1)/255;
    var col2 = color(squ.col);
    var r2 = red(col2)/255;
    var g2 = green(col2)/255;
    var b2 = blue(col2)/255;
    shadedSquare(squ.i*u, squ.j*u, squ.s*u, r1, g1, b1, r2, g2, b2);
  }

  resetShader();
}

function createComposition() {
  for (let i = 0; i < 100; i++) {
   //let newSquare = generateSquare();
    let canAdd = true;
    for (let squ of squares) {
      if (squaresIntersect(newSquare, squ) || squaresTouch(newSquare, squ)) {
        canAdd = false;
        break;
      }
    }
    if (canAdd) {
     // squares.push(newSquare);
    }
  }
}

function squaresIntersect(squ1, squ2) {
  return ((squ1.i <= squ2.i && squ1.i+squ1.s > squ2.i) || (squ2.i <= squ1.i && squ2.i+squ2.s > squ1.i)) && ((squ1.j <= squ2.j && squ1.j+squ1.s > squ2.j) || (squ2.j <= squ1.j && squ2.j+squ2.s > squ1.j));
}

function squaresTouch(squ1, squ2) {
  if (((squ1.i <= squ2.i && squ1.i+squ1.s == squ2.i) || (squ2.i <= squ1.i && squ2.i+squ2.s == squ1.i)) && ((squ1.j <= squ2.j && squ1.j+squ1.s > squ2.j) || (squ2.j <= squ1.j && squ2.j+squ2.s > squ1.j))) return true;
  if (((squ1.i <= squ2.i && squ1.i+squ1.s > squ2.i) || (squ2.i <= squ1.i && squ2.i+squ2.s > squ1.i)) && ((squ1.j <= squ2.j && squ1.j+squ1.s == squ2.j) || (squ2.j <= squ1.j && squ2.j+squ2.s == squ1.j))) return true;
  return false;
}

function generateSquare() {
  let s = randInt(1, 2.25);
  let i = randInt(margin, N-margin-s+1);
  let j = randInt(margin, N-margin-s+1);
  let squ = {
    i: i,
    j: j,
    s: s,
    col: random([col, col, "#fffbe6"])
  };
  return squ;
}

function shadedSquare(x, y, s, r1, g1, b1, r2, g2, b2) {
  theShader.setUniform("u_r1", r1);
  theShader.setUniform("u_g1", g1);
  theShader.setUniform("u_b1", b1);
  theShader.setUniform("u_r2", r2);
  theShader.setUniform("u_g2", g2);
  theShader.setUniform("u_b2", b2);
  push();
  shader(theShader);
  square(x, y, s);
  pop();
}

// === Tab: frag ===
const frag = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  varying vec2 vTexCoord;

  uniform vec2 u_resolution;
  uniform float u_r1;
  uniform float u_g1;
  uniform float u_b1;
  uniform float u_r2;
  uniform float u_g2;
  uniform float u_b2;
  //uniform vec2 u_mouse;
  uniform float u_time;

  float random(in vec2 st) {
      return fract(sin(dot(st.xy,
                           vec2(12.9898,78.233)))
                   * 43758.5453123);
  }

  // 2D Noise based on Morgan McGuire @morgan3d
  // https://www.shadertoy.com/view/4dS3Wd
  float noise (in vec2 st) {
      vec2 i = floor(st);
      vec2 f = fract(st);

      // Four corners in 2D of a tile
      float a = random(i);
      float b = random(i + vec2(1.0, 0.0));
      float c = random(i + vec2(0.0, 1.0));
      float d = random(i + vec2(1.0, 1.0));

      // Smooth Interpolation

      // Cubic Hermine Curve.  Same as SmoothStep()
      vec2 u = f*f*(3.0-2.0*f);
      // u = smoothstep(0.,1.,f);

      // Mix 4 coorners percentages
      return mix(a, b, u.x) +
              (c - a)* u.y * (1.0 - u.x) +
              (d - b) * u.x * u.y;
  }

  float fbm(in vec2 x) {    
      float H = 1.;
      float G = exp2(-H);
      float f = 1.0;
      float a = 1.0;
      float t = 0.0;
      const int numOctaves = 5;
			/*
      for (int i = 0; i < numOctaves; i++) {
          t += a*noise(f*x);
          f *= 2.0;
          a *= G;
      }
			*/
			// i = 0
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 1
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 2
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 3
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 4
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;

      return t;
  }

  float pattern(in vec2 p) {
      vec2 q = vec2( fbm( p + vec2(0.0,0.0) ),
                     fbm( p + vec2(5.2,1.3) ) );

      vec2 r = vec2( fbm( p + 2.0*q + vec2(1.7,9.2) ),
                     fbm( p + 2.0*q + vec2(8.3,2.8) ) );

      return fbm( p + 2.*r + vec2(u_time) );
  }

  void main() {
      vec2 st = gl_FragCoord.xy/u_resolution.xy;
      st.x *= u_resolution.x/u_resolution.y;

      st *= 2.5;
      float pat = pow(clamp(pattern(st), 0., 1.), 3.);
      float r = mix(u_r1, u_r2, pat);
      float g = mix(u_g1, u_g2, pat);
      float b = mix(u_b1, u_b2, pat);

      //vec3 color = vec3(u_r, u_g, u_b)*pat;

      gl_FragColor = vec4(r, g, b, 1.0);
  }
`;

// === Tab: vert ===
const vert = `
   attribute vec3 aPosition;
   attribute vec2 aTexCoord;
   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;
   varying vec2 vTexCoord;

   void main() {
     vTexCoord = aTexCoord;
     vec4 position = vec4(aPosition, 1.0);
     gl_Position = uProjectionMatrix * uModelViewMatrix * position;
   }
`;

